//! End-to-end check that Protobuf Editions features and proto2 groups survive
//! *code generation*, not just descriptor construction.
//!
//! `build.rs` compiles two schemas through the native parser and runs
//! `oxiproto-codegen` over the resulting descriptor sets; this test includes the
//! generated Rust and compares its wire output against hand-computed bytes.

// Generated by `emit_editions_fixture` in build.rs. Machine-emitted code is not
// written to satisfy clippy, so lints are silenced for it (matching
// `tests/recursion_dos.rs`).
#[allow(clippy::all, dead_code)]
mod fixture {
    include!(concat!(env!("OUT_DIR"), "/editions_fixture.rs"));
}

use fixture::{edfix, p2fix, p3fix};

use oxiproto::OxiMessage;

// ---------------------------------------------------------------------------
// features.message_encoding = DELIMITED
// ---------------------------------------------------------------------------

/// A DELIMITED field is framed by start/end-group tags; the sibling field with
/// the default LENGTH_PREFIXED encoding keeps the varint length prefix. Both
/// live in the same generated struct, so this also proves the two paths do not
/// share state.
#[test]
fn delimited_and_length_prefixed_fields_encode_differently() {
    let outer = edfix::Outer {
        delim: Some(Box::new(edfix::Inner {
            x: 9,
            ..Default::default()
        })),
        ..Default::default()
    };

    let bytes = outer.encode_to_vec();
    // field 1, SGroup → (1 << 3) | 3 = 0x0b
    // inner field 1, Varint → 0x08, value 9
    // field 1, EGroup → (1 << 3) | 4 = 0x0c
    assert_eq!(bytes, vec![0x0b, 0x08, 0x09, 0x0c]);
    assert_eq!(outer.encoded_len(), bytes.len());

    let outer = edfix::Outer {
        framed: Some(Box::new(edfix::Inner {
            x: 9,
            ..Default::default()
        })),
        ..Default::default()
    };
    let bytes = outer.encode_to_vec();
    // field 2, Len → 0x12, length 2, then the inner field.
    assert_eq!(bytes, vec![0x12, 0x02, 0x08, 0x09]);
    assert_eq!(outer.encoded_len(), bytes.len());
}

/// Decoding a delimited field has to consume the matching end-group tag and
/// stop there, leaving any following field intact.
#[test]
fn delimited_field_round_trips_and_stops_at_the_end_group_tag() {
    let original = edfix::Outer {
        delim: Some(Box::new(edfix::Inner {
            x: 42,
            ..Default::default()
        })),
        packed: vec![1, 2, 3],
        ..Default::default()
    };

    let bytes = original.encode_to_vec();
    let decoded = edfix::Outer::decode(&bytes[..]).expect("decode");
    assert_eq!(decoded.delim.as_deref().map(|i| i.x), Some(42));
    assert_eq!(decoded.packed, vec![1, 2, 3]);
    assert_eq!(decoded.encode_to_vec(), bytes);
}

// ---------------------------------------------------------------------------
// features.repeated_field_encoding
// ---------------------------------------------------------------------------

/// EXPANDED emits one tag per element; PACKED (the edition default) emits a
/// single length-delimited run.
#[test]
fn repeated_field_encoding_is_honoured_by_generated_code() {
    let msg = edfix::Outer {
        expanded: vec![1, 2],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    // field 3, Varint → (3 << 3) | 0 = 0x18, once per element.
    assert_eq!(bytes, vec![0x18, 0x01, 0x18, 0x02]);
    assert_eq!(msg.encoded_len(), bytes.len());

    let msg = edfix::Outer {
        packed: vec![1, 2],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    // field 4, Len → 0x22, payload length 2.
    assert_eq!(bytes, vec![0x22, 0x02, 0x01, 0x02]);
    assert_eq!(msg.encoded_len(), bytes.len());

    // Both encodings decode back to the same list.
    let decoded = edfix::Outer::decode(&[0x18u8, 0x01, 0x18, 0x02][..]).expect("decode");
    assert_eq!(decoded.expanded, vec![1, 2]);
}

// ---------------------------------------------------------------------------
// proto2 groups
// ---------------------------------------------------------------------------

/// A proto2 `group` generates a real nested struct — before group support it
/// degraded to a `String` field and silently produced wrong bytes.
#[test]
fn proto2_group_generates_a_message_and_round_trips() {
    let msg = p2fix::WithGroup {
        lead: 5,
        sub: Some(Box::new(p2fix::WithGroup_Sub {
            y: 7,
            ..Default::default()
        })),
        ..Default::default()
    };

    let bytes = msg.encode_to_vec();
    // field 1 varint = 5; field 2 SGroup (0x13), inner field 1 varint = 7,
    // field 2 EGroup (0x14).
    assert_eq!(bytes, vec![0x08, 0x05, 0x13, 0x08, 0x07, 0x14]);
    assert_eq!(msg.encoded_len(), bytes.len());

    let decoded = p2fix::WithGroup::decode(&bytes[..]).expect("decode");
    assert_eq!(decoded.lead, 5);
    assert_eq!(decoded.sub.as_deref().map(|s| s.y), Some(7));
    assert_eq!(decoded.encode_to_vec(), bytes);
}

// ---------------------------------------------------------------------------
// Regressions found while wiring the fixtures up
// ---------------------------------------------------------------------------

/// A packed repeated scalar has to be decoded out of the *nested* packed buffer.
/// Generated code used to run the element loop against the enclosing message's
/// buffer, which consumed the following fields (and errored with
/// `UnexpectedEof`) instead of reading the packed run.
#[test]
fn packed_repeated_scalar_decodes_from_the_packed_run_only() {
    // field 4 packed run [1,2,3], then field 3 expanded element 9.
    let bytes = [0x22u8, 0x03, 1, 2, 3, 0x18, 9];
    let decoded = edfix::Outer::decode(&bytes[..]).expect("decode");
    assert_eq!(decoded.packed, vec![1, 2, 3]);
    assert_eq!(decoded.expanded, vec![9]);
}

/// A nested message referenced from a sibling field must resolve to the
/// flattened `Parent_Child` name that codegen actually emits.
#[test]
fn nested_group_type_is_referenced_by_its_flattened_name() {
    // Simply naming the type is the assertion: before the registry fix the
    // generated struct field referred to a non-existent bare `Sub`.
    let sub = p2fix::WithGroup_Sub {
        y: 1,
        ..Default::default()
    };
    assert_eq!(sub.encoded_len(), 2);
}

// ---------------------------------------------------------------------------
// Default repeated packing per syntax (protoc parity)
// ---------------------------------------------------------------------------

/// proto2's default for a repeated packable scalar is **unpacked**: one tag per
/// element. `protoc` only packs a proto2 field when the schema says
/// `[packed = true]`. Generating packed bytes here is a silent
/// wire-compatibility divergence, because a peer that re-serialises the message
/// from its own proto2 schema emits the expanded form.
#[test]
fn proto2_repeated_scalar_defaults_to_unpacked() {
    let msg = p2fix::DefaultPacking {
        vals: vec![1, 2, 3],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    // field 1, Varint (0x08) per element — no length-delimited run.
    assert_eq!(bytes, vec![0x08, 0x01, 0x08, 0x02, 0x08, 0x03]);
    assert_eq!(msg.encoded_len(), bytes.len());
}

/// An explicit `[packed = true]` overrides the proto2 default.
#[test]
fn proto2_explicit_packed_option_wins() {
    let msg = p2fix::DefaultPacking {
        forced: vec![1, 2, 3],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    // field 2, Len (0x12), payload length 3.
    assert_eq!(bytes, vec![0x12, 0x03, 0x01, 0x02, 0x03]);
    assert_eq!(msg.encoded_len(), bytes.len());
}

/// Decoding must stay permissive in both directions regardless of the schema
/// default: a proto2 reader accepts a packed run, and vice versa.
#[test]
fn proto2_unpacked_field_still_decodes_a_packed_run() {
    let decoded = p2fix::DefaultPacking::decode(&[0x0au8, 0x03, 1, 2, 3][..]).expect("decode");
    assert_eq!(decoded.vals, vec![1, 2, 3]);

    let decoded = p2fix::DefaultPacking::decode(&[0x10u8, 0x01, 0x10, 0x02][..]).expect("decode");
    assert_eq!(decoded.forced, vec![1, 2]);
}

/// proto3's default is packed.
#[test]
fn proto3_repeated_scalar_defaults_to_packed() {
    let msg = p3fix::DefaultPacking {
        vals: vec![1, 2, 3],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    assert_eq!(bytes, vec![0x0a, 0x03, 0x01, 0x02, 0x03]);
    assert_eq!(msg.encoded_len(), bytes.len());
}

/// An explicit `[packed = false]` overrides the proto3 default.
#[test]
fn proto3_explicit_packed_false_wins() {
    let msg = p3fix::DefaultPacking {
        expanded: vec![1, 2],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    assert_eq!(bytes, vec![0x10, 0x01, 0x10, 0x02]);
    assert_eq!(msg.encoded_len(), bytes.len());
}

/// Editions 2023 defaults `features.repeated_field_encoding` to PACKED, so a
/// field that writes no feature packs — like proto3, unlike proto2.
#[test]
fn editions_repeated_scalar_defaults_to_packed() {
    let msg = edfix::DefaultPacking {
        vals: vec![1, 2, 3],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    assert_eq!(bytes, vec![0x0a, 0x03, 0x01, 0x02, 0x03]);
    assert_eq!(msg.encoded_len(), bytes.len());
}

/// `encoded_len` must agree with `encode_raw` for a *non-varint* expanded
/// field too. The expanded size formula uses the element's own wire type, which
/// is the one input that differs for I32/I64 fields — and a mismatch here is
/// not a mis-sized buffer but a corrupt length prefix on any enclosing message.
#[test]
fn proto2_expanded_encoded_len_matches_non_varint_elements() {
    let msg = p2fix::DefaultPacking {
        wide: vec![1, 2, 3],
        reals: vec![1.5, 2.5],
        ..Default::default()
    };
    let bytes = msg.encode_to_vec();
    assert_eq!(
        msg.encoded_len(),
        bytes.len(),
        "encoded_len disagreed with encode_raw: {bytes:02x?}"
    );

    // field 3, I64 (0x19) per element: 3 × (1 + 8) = 27 bytes.
    // field 4, I64 (0x21) per element: 2 × (1 + 8) = 18 bytes.
    assert_eq!(bytes.len(), 27 + 18);
    assert_eq!(bytes.iter().filter(|b| **b == 0x19).count(), 3);
    assert_eq!(bytes.iter().filter(|b| **b == 0x21).count(), 2);

    let decoded = p2fix::DefaultPacking::decode(&bytes[..]).expect("decode");
    assert_eq!(decoded.wide, vec![1, 2, 3]);
    assert_eq!(decoded.reals, vec![1.5, 2.5]);
}
